/* Courses, independent vehicle categories and transport work. */
(function(root){
'use strict';
const courses={car:{name:'Права на автомобиль',months:3,age:18,price:.035},moto:{name:'Права на мотоцикл',months:2,age:18,price:.025},truck:{name:'Права на грузоперевозки',months:4,age:21,price:.06}};
const now=()=>S.age*12+Math.floor((S.t||0)*12+1e-7);
function state(){if(!S.lifelineTransport){const licenses={};if(S.owns.car!=null&&S.owns.car!==false)licenses.car=true;if(S.owns.moto!=null&&S.owns.moto!==false)licenses.moto=true;if(S.job==='driver')licenses.truck=true;if(S.flags.usLic>=16)licenses.car=true;S.flags.usLic=-1;S.lifelineTransport={version:1,licenses,course:null,mode:S.owns.car?'car':S.owns.moto?'moto':'bus',asked:S.age>=19,lastJobTry:-1};}return S.lifelineTransport;}
function licensed(kind){return !!state().licenses[kind]&&S.flags.licRet==null&&!licOff();}
function price(kind){return incomeAt(C(),.5)*courses[kind].price;}
function options(){const t=state();return Object.entries(courses).map(([id,c])=>({id:'driving-course-'+id,title:c.name,cost:price(id),note:c.months+' мес. · обучение и экзамен',disabled:S.age<c.age||!!t.licenses[id]||!!t.course||S.job==='prison'||noSight()||S.flags.licRet!=null||S.money<price(id),reason:t.licenses[id]?'Категория уже открыта':t.course?'Сначала завершите текущий курс':S.age<c.age?'С '+c.age+' лет':S.flags.licRet!=null||noSight()?'Сейчас вождение недоступно':S.money<price(id)?'Недостаточно денег на курс':''}));}
function actions(){if(S.age<16||S.phase!=='life')return [];const t=state(),list=options();list.push({id:'transport-bus',title:'Общественный транспорт',cost:0,note:'Базовые поездки входят в бытовые расходы',disabled:t.mode==='bus',reason:t.mode==='bus'?'Выбран':''});if(S.owns.bike)list.push({id:'transport-bike',title:'Ездить на велосипеде',cost:0,disabled:t.mode==='bike',reason:t.mode==='bike'?'Выбран':''});if(licensed('truck'))for(const [key,title]of [['driver','Искать работу водителем грузовика'],['manager','Искать работу в управлении перевозками']])list.push({id:'transport-job-'+key,title,cost:0,note:'Отклик на вакансию · трудоустройство не гарантировано',disabled:t.lastJobTry===S.age||(key==='manager'&&(S.edu<3||!(S.exp?.driver?.[0]>=2||S.job==='driver'&&S.jobY>=2))),reason:t.lastJobTry===S.age?'Уже искали в этом году':key==='manager'&&S.edu<3?'Нужно профессиональное образование':key==='manager'&&!(S.exp?.driver?.[0]>=2||S.job==='driver'&&S.jobY>=2)?'Нужно два года опыта в перевозках':''});return list;}
function perform(id){if(!/^driving-course-|^transport-/.test(id))return false;if(S.pending||LifelineMoments.pending()||S.phase!=='life')throw Error('Сначала завершите текущий выбор');const item=actions().find(a=>a.id===id);if(!item||item.disabled)throw Error(item?.reason||'Действие недоступно');const t=state();if(id.startsWith('driving-course-')){const kind=id.slice(15);S.money-=item.cost;book('Обучение вождению',-item.cost);t.course={kind,started:now(),due:now()+courses[kind].months,paid:item.cost};log('Вы оплатили курс «'+courses[kind].name+'». Обучение и экзамен займут '+courses[kind].months+' мес.','note');}else if(id.startsWith('transport-job-')){const job=id.endsWith('manager')?'clerk':'driver';t.lastJobTry=S.age;if(chance(.65)){takeJob({id:job,pct:job==='clerk'?.55:.45,formal:true});t.logisticsManager=job==='clerk';log(job==='driver'?'Вы устроились водителем в грузоперевозках.':'Вы устроились координатором перевозок.','warm');}else log('Вакансию в перевозках получил другой кандидат. Можно попробовать в следующем году.','note');}else{t.mode=id==='transport-bike'?'bike':'bus';log(t.mode==='bike'?'Вы выбрали велосипед для повседневных поездок.':'Вы выбрали общественный транспорт.','note');}return true;}
function invitation(){const item=options().find(o=>o.id==='driving-course-car');return {title:'Хотите получить права?',body:'Можно пройти обучение и экзамен на автомобиль. Без прав доступны велосипед и общественный транспорт. Категории мотоцикла и грузоперевозок изучаются отдельно.',choices:[{k:'yes',label:'Записаться на курс',sub:wonStr(item.cost)+' · 3 месяца',dis:item.disabled},{k:'no',label:'Пока без прав',sub:'Велосипед или общественный транспорт'}]};}
function observe(){const t=state();if(t.course&&now()>=t.course.due){const kind=t.course.kind;t.licenses[kind]=true;t.course=null;log('Вы завершили обучение и сдали экзамен: '+courses[kind].name+'.', 'warm');}if(S.age>=18&&!t.asked&&!S.pending&&!LifelineMoments.pending()){t.asked=true;LifelineMoments.enqueue('lifeline-driving-intro',invitation());}}
function adaptPending(){if(S.pending?.id==='buy'&&['car','moto'].includes(S.pending.p?.item)&&!licensed(S.pending.p.item))S.pending.view=invitation();}
function summary(){const t=state();return {licenses:Object.keys(t.licenses).filter(k=>t.licenses[k]).map(k=>courses[k].name),mode:{bus:'Общественный транспорт',bike:'Велосипед',car:'Автомобиль',moto:'Мотоцикл'}[t.mode],course:t.course?{name:courses[t.course.kind].name,monthsLeft:Math.max(0,t.course.due-now())}:null};}
function install(){ITEMS.car.age=18;ITEMS.moto.only=()=>true;const originalItems=shopItems;shopItems=function(...args){const items=originalItems(...args).filter(i=>i.id!=='own_car'||licensed('car')).filter(i=>i.id!=='own_moto'||licensed('moto'));if(licensed('moto')&&!S.owns.moto&&S.age>=18&&S.job!=='prison'&&!items.some(i=>i.id==='own_moto')){const cost=itemPrice('moto');items.push({id:'own_moto',n:'Купить мотоцикл',d:'Для поездок · требуется отдельная категория',price:cost,avail:canPay(cost),credit:onCredit(cost)&&canPay(cost),why:payWhy(cost)});}return items;};const originalBuyable=buyable;buyable=function(items){return originalBuyable((items||['phone','tv','moto','car','house']).filter(k=>!['car','moto'].includes(k)));};const buyBuild=DEC.buy.build,buyApply=DEC.buy.apply;DEC.buy.build=function(p){if(['car','moto'].includes(p.item)&&!licensed(p.item))return invitation();return buyBuild(p);};DEC.buy.apply=function(key,p,...args){if(['car','moto'].includes(p.item)&&!licensed(p.item)){if(key==='yes'){const item=options().find(o=>o.id==='driving-course-car');if(item.disabled)throw Error(item.reason);S.money-=item.cost;book('Обучение вождению',-item.cost);state().course={kind:'car',started:now(),due:now()+3,paid:item.cost};return 'Вы записались на обучение вождению автомобиля.';}return 'Вы пока пользуетесь велосипедом или общественным транспортом.';}return buyApply(key,p,...args);};const offers=jobOffers;jobOffers=function(...args){return offers(...args).filter(o=>o.id!=='driver'||licensed('truck')).filter(o=>o.id!=='delivery'||licensed('moto')||licensed('car')||!!S.owns.bike);};const take=takeJob;takeJob=function(offer,...args){if(offer.id==='driver'&&!licensed('truck'))throw Error('Для работы водителем нужна категория грузоперевозок');return take(offer,...args);};const resolve=LifelineMoments.resolve;LifelineMoments.resolve=function(key,extra){if(LifelineMoments.pending()?.id==='lifeline-driving-intro'&&key==='yes'){const item=options().find(o=>o.id==='driving-course-car');if(item.disabled)throw Error(item.reason);S.money-=item.cost;book('Обучение вождению',-item.cost);state().course={kind:'car',started:now(),due:now()+3,paid:item.cost};log('Вы записались на обучение вождению автомобиля.','note');}return resolve(key,extra);};}
root.LifelineTransport={adaptPending,state,licensed,options,actions,perform,observe,summary,install};
})(self);
